/* Visual journey simulation only. No authentication, network or production data. */
'use strict'
const key='uzum-merch-visual-demo-v1'
const people={
 alice:{name:'Алина Тестовая',email:'alice@example.invalid',legal:'Тестовое юрлицо E-com',department:'Тестовый отдел',shop:'E-com',scope:'catalog',source:'корпоративного источника',method:'corporate'},
 boris:{name:'Борис Тестовый',email:'boris@example.invalid',legal:'Тестовое юрлицо Fintech',department:'Онбординг (тест)',shop:'Fintech',scope:'welcome',source:'корпоративного источника',method:'corporate'},
 guest:{name:'Гость Тестовый',email:'',legal:'Тестовое юрлицо Technologies',department:'Склад (тест)',shop:'Technologies',scope:'catalog',source:'реестра сотрудников',method:'identifier'}
}
let state
try{state=JSON.parse(localStorage.getItem(key))||{}}catch{state={}}
if(!people[state.user])delete state.user
if(!Array.isArray(state.orders))state.orders=[]
const root=document.querySelector('#app')
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{/* browser storage may be disabled */}}
const progress=step=>`<div class="steps">${['Приглашение','Вход','Выбор мерча','Получение'].map((s,i)=>`<span class="step ${i===step?'active':''}">${i+1}. ${s}</span>`).join('')}</div>`
function home(){
 root.innerHTML=`<span class="eyebrow">Пример будущего пользовательского пути</span><h1>Мерч начинается с простого входа</h1><p class="muted">Посмотрите два сценария: корпоративный аккаунт или персональное приглашение с идентификатором.</p>${progress(0)}<div class="grid"><section class="card"><div class="portalmark">↗</div><h2>Корпоративный аккаунт</h2><p>Сотрудник получает приглашение на рабочую почту. Входит привычным корпоративным аккаунтом, без нового пароля мерчшопа.</p><button data-action="portal">Открыть тестовое приглашение</button></section><section class="card"><div class="portalmark">#</div><h2>Вход по идентификатору</h2><p>Сотрудник получает персональную ссылку и вводит свой идентификатор. Данные уже есть в реестре.</p><button data-action="guest" class="secondary">Открыть персональную ссылку</button></section></div>${state.user?'<section class="card"><h2>Вход уже сохранён в этом браузере</h2><button data-action="shop">Вернуться в свой магазин</button></section>':''}<div class="note">Это имитация экранов, а не подключение Keycloak. Не вводите реальные пароли или персональные данные. Защита протокола проверяется в отдельном Docker-стенде, не в этой демоверсии.</div>`
}
function portal(){
 root.innerHTML=`${progress(1)}<section class="card portal"><div class="portalmark">K</div><span class="eyebrow">Имитация корпоративного входа</span><h1>Выберите тестового сотрудника</h1><p class="muted">В реальном подключении здесь будет корпоративная авторизация Keycloak. Настоящий пароль не требуется.</p><label>Сценарий<select id="account"><option value="alice">Алина — основной каталог E-com</option><option value="boris">Борис — Welcome pack Fintech</option><option value="outsider">Сотрудник без доступа к мерчу</option><option value="blocked">Заблокированный корпоративный аккаунт</option></select></label><button id="corporate-login">Продолжить</button><button data-action="home" class="quiet">Назад</button><p class="note">ФИО, email, юрлицо и отдел будут показаны как полученные от корпоративного источника. Разрешение на мерч задаёт реестр.</p></section>`
 document.querySelector('#corporate-login').onclick=()=>{
  const value=document.querySelector('#account').value
  if(['outsider','blocked'].includes(value)){delete state.user;save();return denied(value)}
  state.user=value;save();shop()
 }
}
function denied(value){root.innerHTML=`${progress(1)}<section class="card portal"><h1>Доступ закрыт</h1><p>${value==='blocked'?'Корпоративный аккаунт заблокирован. Вход не выполнен.':'Личность подтверждена, но в реестре нет разрешения на мерч.'}</p><p class="muted">В демо это заранее заданный сценарий, не ответ корпоративной системы.</p><button data-action="portal">Другой тестовый сотрудник</button></section>`}
function guest(){
 root.innerHTML=`${progress(1)}<section class="card portal"><div class="portalmark">#</div><h1>Персональное приглашение</h1><p>Тестовый идентификатор: <b>DEMO-001</b>. Почта и пароль не требуются.</p>${state.claimed?'<p class="note">Приглашение уже активировано в этом браузере. Если вход сохранён, вернитесь в магазин; иначе сбросьте демо для повторной проверки.</p><button data-action="shop">Открыть магазин</button>':'<form id="guest-form"><label>Идентификатор<input name="identifier" required autocomplete="off" placeholder="DEMO-001" maxlength="40"></label><button>Активировать приглашение</button><p id="error" class="error" role="alert"></p></form>'}<p class="muted">Однократность здесь имитируется только в текущем браузере. В отдельном техническом прототипе она обеспечивается транзакцией БД.</p><button data-action="home" class="quiet">Назад</button></section>`
 document.querySelector('#guest-form')?.addEventListener('submit',e=>{e.preventDefault();if(e.target.identifier.value.trim()!=='DEMO-001'){document.querySelector('#error').textContent='Идентификатор не совпадает. Используйте DEMO-001.';return}state.user='guest';state.claimed=true;save();shop()})
}
function shop(){
 const p=people[state.user];if(!p)return home()
 const welcome=p.scope==='welcome',products=welcome?[['welcome-shirt','Футболка Welcome','👕'],['welcome-book','Блокнот Welcome','📓']]:[['shirt','Футболка','👕'],['bag','Шоппер','🛍'],['book','Блокнот','📓']]
 root.innerHTML=`<div class="row"><div class="grow"><span class="eyebrow">${escape(p.shop)} · тестовый магазин</span><h1>${welcome?'Welcome pack':'Выберите свой мерч'}</h1></div><button data-action="logout" class="secondary">Выйти</button></div>${progress(2)}<div class="grid"><section><form id="checkout"><div class="products">${products.map(([id,name,icon])=>`<article class="product"><div class="art">${icon}</div><div class="body"><label><input type="checkbox" name="item" value="${id}" data-name="${name}">${name}</label><label>Размер<select data-size="${id}"><option>Стандартный</option>${id.includes('shirt')?'<option>S</option><option>M</option><option>L</option>':''}</select></label><label>Цвет<select data-color="${id}"><option>Как на фото</option><option>Фиолетовый</option></select></label></div></article>`).join('')}</div><section class="card"><h2>Как получить заказ?</h2><label>Способ получения<select name="mode"><option value="office">Заберу в офисе</option>${!welcome?'<option value="shipping">Я удалёнщик — отправьте в мою страну</option>':''}${!welcome&&p.method==='identifier'?'<option value="pvz">Заберу в своём ПВЗ</option>':''}</select></label><div data-mode="office"><label>Офис<select name="office"><option>Офис 1 (тест)</option><option>Офис 2 (тест)</option></select></label></div><div data-mode="shipping" class="hidden"><label>Страна<input name="country" maxlength="100" placeholder="Тестовая страна"></label><label>Город<input name="city" maxlength="100" placeholder="Тестовый город"></label><label>Адрес доставки<input name="address" maxlength="200" placeholder="Тестовый адрес"></label></div><div data-mode="pvz" class="hidden"><label>Код ПВЗ<input name="pvz" maxlength="50" placeholder="TEST-123"></label></div><label>Телефон для получения<input name="phone" readonly value="+000 000 00 00"><span class="muted">В демонстрации используем вымышленный номер.</span></label><div id="comment-wrap" class="hidden"><label>Комментарий (необязательно)<textarea name="comment" maxlength="500" placeholder="Только вымышленные сведения"></textarea></label></div><div id="selection" class="note">Выберите товары выше. Список появится здесь перед оформлением.</div><p id="error" class="error" role="alert"></p><button>Оформить тестовый заказ</button></section></form></section><aside><section class="card"><h2>Данные сотрудника</h2><p class="muted">Предзаполнены из ${p.source}, редактирование недоступно.</p>${[['ФИО',p.name],['Юрлицо',p.legal],['Отдел',p.department],['Email',p.email||'Не требуется для этого входа']].map(([label,value])=>`<label>${label}<input readonly value="${escape(value)}"></label>`).join('')}<span class="pill">Доступ: ${escape(p.shop)} / ${welcome?'Welcome pack':'Каталог'}</span></section><section class="card"><h2>Мои тестовые заказы</h2>${state.orders.filter(o=>o.user===state.user).map(o=>`<div class="order"><b>${escape(o.number)}</b><p>${escape(o.items.map(i=>i.name).join(', '))}</p><span class="pill">Заявка · демо</span></div>`).join('')||'<p class="muted">Пока нет заказов.</p>'}</section><div class="note">Все проверки здесь демонстрационные и выполняются в браузере. Это не настоящая авторизация и не подтверждение безопасности.</div></aside></div>`
 const form=document.querySelector('#checkout')
 const selected=()=>[...form.querySelectorAll('[name=item]:checked')].map(x=>({name:x.dataset.name,size:form.querySelector(`[data-size="${x.value}"]`).value,color:form.querySelector(`[data-color="${x.value}"]`).value}))
 form.addEventListener('change',()=>{document.querySelectorAll('[data-mode]').forEach(el=>el.classList.toggle('hidden',el.dataset.mode!==form.mode.value));document.querySelector('#comment-wrap').classList.toggle('hidden',form.mode.value==='office');document.querySelector('#selection').textContent=selected().map(i=>`${i.name} · ${i.size} · ${i.color}`).join('; ')||'Выберите товары выше.'})
 form.addEventListener('submit',e=>{e.preventDefault();const items=selected(),mode=form.mode.value;const error=document.querySelector('#error');if(!items.length){error.textContent='Выберите хотя бы один товар.';return}if(mode==='shipping'&&['country','city','address'].some(k=>!form[k].value.trim())){error.textContent='Укажите тестовые страну, город и адрес.';return}if(mode==='pvz'&&!form.pvz.value.trim()){error.textContent='Укажите тестовый код ПВЗ.';return}const number='DEMO-'+String(state.orders.length+1).padStart(4,'0');const order={number,user:state.user,items,mode,office:mode==='office'?form.office.value:'',phone:'+000 000 00 00'};state.orders.push(order);save();complete(order)})
}
function complete(order){const p=people[state.user];root.innerHTML=`${progress(3)}<section class="card portal"><div class="portalmark">✓</div><h1 class="success">Тестовый заказ принят</h1><p>Номер <b>${escape(order.number)}</b></p><ul>${order.items.map(i=>`<li>${escape(i.name)} · ${escape(i.size)} · ${escape(i.color)}</li>`).join('')}</ul><p>${order.mode==='office'?`Получение: ${escape(order.office)}. Дату и время сообщит ответственный.`:'С вами свяжутся для организации доставки.'}</p><p class="note">Заказ сохранён только в этом браузере. Реального резерва, отправки писем и выдачи не происходит. QR-код в этой демонстрации не формируется.</p><button data-action="shop">Вернуться в ${p.scope==='welcome'?'Welcome pack':'каталог'}</button></section>`}
root.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='logout'){delete state.user;save();home()}else({home,portal,guest,shop}[action]?.())})
document.querySelector('#reset').onclick=()=>{localStorage.removeItem(key);state={orders:[]};home()}
if(state.user){shop()}else{home()}
